// Hand-written exam banks for the original lessons in seed.js, keyed by slug. Format: SCHEMA.md → "Exam bank"
// Helpers keep the data compact. In every choice question the FIRST option is the correct answer
// (the server shuffles options before showing them).
const F = (question, questionEn, options, explanation, explanationEn) =>
  ({ question, questionEn, answer: options[0], options, explanation, explanationEn });
const R = (text, textEn, question, questionEn, options, explanation, explanationEn) =>
  ({ text, textEn, question, questionEn, answer: options[0], options, explanation, explanationEn });
const L = (script, scriptEn, question, questionEn, options, explanation, explanationEn) =>
  ({ script, scriptEn, question, questionEn, answer: options[0], options, explanation, explanationEn });
const W = (question, questionEn, answer, answerEn, tip) => ({ question, questionEn, answer, answerEn, tip });
const S = (question, questionEn, answer, answerEn, pronunciation, tip) =>
  ({ question, questionEn, answer, answerEn, pronunciation, tip });

